fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 1800);
        host::display::state_set(2, 0);
        host::display::state_set(3, 1);
        host::display::state_set(4, 0);
        host::display::state_set(5, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(6) == 0;
    host::display::state_set(6, down);
    if host::display::state_get(5) == 1 {
        host::display::clear(0x101010);
        host::display::draw_string(170, 170, "TIME UP", 0xffaa00, 4);
        host::display::draw_string(150, 240, "MOLES HIT", 0x808080, 2);
        host::display::draw_number(330, 234, host::display::state_get(2), 0xffffff, 3);
        host::display::draw_string(140, 320, "TAP TO RESTART", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let mut left: i32 = host::display::state_get(1) - 1;
        if left <= 0 {
            left = 0;
            host::display::state_set(5, 1);
        }
        host::display::state_set(1, left);
        let mut round: i32 = host::display::state_get(3);
        let mut mt: i32 = host::display::state_get(4) + 1;
        if mt >= 45 {
            mt = 0;
            round = round + 1;
        }
        let mole: i32 = hash(round) % 9;
        let mx: i32 = 76 + (mole % 3) * 120;
        let my: i32 = 120 + (mole / 3) * 120;
        if tap {
            let px: i32 = host::display::pointer_x();
            let py: i32 = host::display::pointer_y();
            if px >= mx && px < mx + 110 && py >= my && py < my + 110 {
                host::display::state_set(2, host::display::state_get(2) + 1);
                host::audio::tone(880, 60, 1);
                round = round + 1;
                mt = 0;
            }
        }
        host::display::state_set(3, round);
        host::display::state_set(4, mt);
        host::display::clear(0x0c1408);
        let mut c: i32 = 0;
        while c < 9 {
            let cx: i32 = 76 + (c % 3) * 120;
            let cy: i32 = 120 + (c / 3) * 120;
            host::display::fill_rect(cx, cy, 110, 110, 0x1c2c14);
            if c == mole {
                host::display::fill_rect(cx + 15, cy + 25, 80, 70, 0xcc8833);
                host::display::fill_rect(cx + 32, cy + 45, 12, 12, 0x000000);
                host::display::fill_rect(cx + 64, cy + 45, 12, 12, 0x000000);
            }
            c = c + 1;
        }
        host::display::draw_string(8, 10, "TIME", 0x808080, 2);
        host::display::draw_number(90, 10, left / 60, 0xffffff, 2);
        host::display::draw_string(w - 180, 10, "HITS", 0x808080, 2);
        host::display::draw_number(w - 100, 10, host::display::state_get(2), 0x00ff88, 2);
    }
    host::display::present();
}
